import { mapState } from 'vuex';
export default {
  name: 'home_radio',
  cname: '单选框',
  icon: 'iconbiaodanzujian-danxuankuang',
  configName: 'c_home_radio',
  type: 0, // 0 基础组件 1 营销组件 2工具组件
  defaultName: 'radios', // 外面匹配名称
  props: {
    index: {
      type: null
    },
    num: {
      type: null
    }
  },
  computed: {
    ...mapState('admin/mobildConfig', ['defaultArray'])
  },
  watch: {
    pageData: {
      handler (nVal, oVal) {
        this.setConfig(nVal)
      },
      deep: true
    },
    num: {
      handler (nVal, oVal) {
        let data = this.$store.state.admin.mobildConfig.defaultArray[nVal]
        this.setConfig(data)
      },
      deep: true
    },
    'defaultArray': {
      handler (nVal, oVal) {
        let data = this.$store.state.admin.mobildConfig.defaultArray[this.num]
        this.setConfig(data);
      },
      deep: true
    }
  },
  data () {
    return {
      defaultConfig: {
        name: 'radios',
        timestamp: this.num,
        titleConfig: {
          title: '标题',
          value: '单选框',
          place: '请输入标题',
          max: 10,
          type: 'form'
        },
        wordsConfig: {
          title:'选项',
          list: [
            { val: '选项一', show: true},
            { val: '选项二', show: false}
          ]
        },
        titleShow: {
          title: '是否必填',
          val: false,
          type:'form'
        },
      },
      titleTxt: '',
      pageData: {},
      list: []
    }
  },
  mounted () {
    this.$nextTick(() => {
      this.pageData = this.$store.state.admin.mobildConfig.defaultArray[this.num]
      this.setConfig(this.pageData)
    })
  },
  methods: {
    setConfig (data) {
      if(!data) return
      if(data.titleConfig){
        this.titleTxt = data.titleConfig.value;
        this.list = data.wordsConfig.list;
      }
    }
  }
}
